function SearchDeckModal({request,cards,onConfirm}:{request:SearchRequest;cards:CardDef[];onConfirm:(ids:string[])=>void}){
 const [selected,setSelected]=useState<string[]>([]),valid=cards.filter(card=>matchesSearch(card,request)),required=Math.min(request.limit,valid.length),ready=request.optional?selected.length<=required:selected.length===required;
 const toggle=(card:CardDef)=>{if(!matchesSearch(card,request))return;setSelected(current=>current.includes(card.id)?current.filter(id=>id!==card.id):current.length<required?[...current,card.id]:current)};
 return <div className="overlay search-deck-overlay"><section className="search-deck-dialog" role="dialog" aria-modal="true" aria-labelledby="search-title">
  <header><div><span>EFEITO DE PROCURE · SOMENTE VOCÊ VÊ ESTE DECK</span><h2 id="search-title">{request.sourceName}</h2></div><b>{cards.length} cartas no Deck Principal</b></header>
  <div className="search-instruction"><p>Escolha {request.optional?"até ":""}<strong>{required}</strong> {request.filterLabel}. Todas as cópias físicas aparecem separadamente.</p><span>{request.destination==="field"?"Destino: campo":"Destino: sua mão"}{request.reveal?" · ficará revelada ao oponente enquanto estiver na mão":" · informação privada"}</span></div>
  <div className="search-card-grid">{valid.length?valid.map((card,index)=>{const chosen=selected.includes(card.id);return <div className={`search-valid ${chosen?"search-selected":""}`} key={`${card.id}-${index}`}><OriginalCard card={card} small inspectable={false} selected={chosen} onClick={()=>toggle(card)}/><b>{card.name}</b><small>Cópia válida {index+1} · custo {card.cost}</small></div>}):<div className="search-empty"><b>Nenhuma carta corresponde</b><span>O Deck Principal não possui uma opção válida para este efeito.</span></div>}</div>
  <footer><span>{selected.length}/{required} selecionada(s)</span>{request.optional&&<button onClick={()=>onConfirm([])}>Não procurar</button>}<button className="confirm-search" disabled={!ready} onClick={()=>onConfirm(selected)}>Confirmar e embaralhar</button></footer>
 </section></div>
}

function ResponseModal({action,player,seconds,passes=0,onPlay,onPass}:{action:string;player:Player;seconds:number;passes?:number;onPlay:(idx:number)=>void;onPass:()=>void}){
 const available=player.hand.map((card,index)=>({card,index,cost:effectiveCost(card,player)})).filter(x=>isFast(x.card));
 return <div className="overlay response-overlay"><section className="response-dialog" role="dialog" aria-modal="true" aria-labelledby="response-title"><header><span>JANELA DE RESPOSTA</span><b className={seconds<=5?"urgent":""}>⏱ {seconds}s</b><b>Reserva · {player.reserve}</b></header><h2 id="response-title">Sua prioridade</h2><div className="priority-status"><b>{passes===0?"Primeiro passe":"Segundo passe"}</b><span>{passes===0?"A prioridade voltará ao jogador da ação.":"A ação será encerrada após este passe."}</span></div><p>O oponente realizou: <strong>{action}</strong>. Use um Feitiço Acelerado ou passe. A partida fica pausada até sua decisão.</p>{available.length?<div className="response-cards">{available.map(({card,index,cost})=><div className={cost>player.reserve?"unavailable":""} key={card.id}><OriginalCard card={card} small inspectable={false} activeEffect="RESPOSTA ACELERADA" disabled={cost>player.reserve} onClick={()=>onPlay(index)}/><b>{card.name}</b><small>{cost>player.reserve?`Requer ${cost} de Reserva`:`Responder · custo ${cost}`}</small></div>)}</div>:<div className="no-response-card"><i>◇</i><b>Nenhuma carta Acelerada na mão</b><span>Confirme para devolver a prioridade.</span></div>}<footer><button className="pass-response" onClick={onPass}>Passar prioridade</button></footer></section></div>
}

function MulliganModal({player,count,waiting,onDecision}:{player:Player;count:number;waiting:boolean;onDecision:(keep:boolean)=>void}){
 const nextSize=Math.max(1,player.hand.length-1);
 return <div className="overlay mulligan-overlay"><section className="mulligan-dialog" role="dialog" aria-modal="true"><header><div><p>MÃO INICIAL · {count?`${count} MULLIGAN${count>1?"S":""}`:"7 CARTAS"}</p><h2>{waiting?"Aguardando o oponente":"Manter ou trocar toda a mão?"}</h2></div><span>Nova mão sempre tem 1 carta a menos</span></header>{waiting?<div className="mulligan-wait"><i></i><b>Sua mão foi mantida</b><span>A partida começa assim que o outro jogador terminar.</span></div>:<><p className="mulligan-help">Se pedir mulligan, todas as {player.hand.length} cartas voltam ao Deck Principal, ele é embaralhado e você compra uma mão nova de {nextSize}. É possível repetir até restar 1 carta.</p><div className="mulligan-cards">{player.hand.map((card,index)=><div className="mulligan-card-static" key={`${card.id}-${index}`}><OriginalCard card={card} small inspectable={false} disabled/></div>)}</div><footer><span>{player.hand.length} carta(s) na sua mão inicial</span><div><button disabled={player.hand.length<=1} onClick={()=>onDecision(false)}>Mulligan → {nextSize}</button><button className="gold" onClick={()=>onDecision(true)}>Manter {player.hand.length}</button></div></footer></>}</section></div>
}
